from pathlib import Path
import re


def load(path):
    p = Path(path)
    raw = p.read_bytes()
    crlf = b'\r\n' in raw
    return p, raw.decode('utf-8').replace('\r\n', '\n'), crlf


def save(p, text, crlf):
    if crlf:
        text = text.replace('\r\n', '\n').replace('\n', '\r\n')
    p.write_bytes(text.encode('utf-8'))


def rep(path, old, new, count=1):
    p, text, crlf = load(path)
    actual = text.count(old)
    assert actual == count, (path, old[:100], actual, count)
    text = text.replace(old, new, count)
    save(p, text, crlf)


def between(path, start, end, replacement):
    p, text, crlf = load(path)
    i = text.find(start)
    assert i >= 0, (path, 'missing start', start)
    j = text.find(end, i + len(start))
    assert j >= 0, (path, 'missing end', end)
    assert text.find(start, i + 1) < 0, (path, 'duplicate start', start)
    text = text[:i] + replacement + text[j:]
    save(p, text, crlf)


