# STOP/settings/replacement/close tests: arm terminal threshold first.
for method in ['Stop','StopAtBoundary','Settings','ReplacedPid','ReplacedOperation','CloseFailure']:
    marker = '        private static void '+method+'()\n'
    pth, text, crlf = load(p)
    i = text.find(marker); assert i>=0
    j = text.find('        private static void ', i+len(marker)); assert j>=0
    block = text[i:j]
    if 'h.Terminal(h.A)' in block and 'ArmFiveMinuteStall' not in block:
        block2 = block.replace('using (var h = new H()) { ', 'using (var h = new H()) { h.ArmFiveMinuteStall(h.A,101); ', 1)
        block2 = block2.replace('using(var h=new H()){', 'using(var h=new H()){h.ArmFiveMinuteStall(h.A,101);', 1)
        text = text[:i] + block2 + text[j:]
        save(pth,text,crlf)

