# Durable repository policy: replace the now-obsolete broad auto-hotkey rule.
p = 'AGENTS.md'
pth, text, crlf = load(p)
start = text.index('## Required autobattle resume verification\n')
end = text.index('## Terminal dialogs and sequential replacement\n', start)
policy = '''## Restart-only autobattle verification and steady-state recovery\n\nAutomatic Autobattle/slave hotkeys are authorized only for a client that 4RTools\nitself has freshly launched/restarted/relogged. Adopting, restoring, maximizing,\nfocusing or observing an already-running client must NEVER arm or send an automatic\nresume hotkey. Manual TESTS -> Resume hotkey remains an explicit diagnostic action.\n\nAfter the restarted client reaches the expected username/character with fresh verified\nX/Y/map/living HP, wait a full 10 seconds, then call the exact same shared ResumeHotkey\nverifier used by the diagnostic. It may send at most three configured hotkeys, each\nfollowed by its own 10-second fresh X/Y observation window; stop immediately on X or Y\nmovement. Missing/unverified/stale state is not zero or movement.\n\nDuring normal online supervision, do not send wakeup hotkeys. Track verified X/Y only.\nAfter five minutes without verified movement, an exact freshly confirmed `Now Logging\nOut.` or `Disconnected from Server.` dialog may trigger an early client restart. Without\none of those exact dialogs, keep waiting. At ten minutes without verified X/Y movement,\nrestart the affected client regardless of visual classification. A healthy sibling stays\nuntouched and dual recovery remains globally serialized.\n\nFailed launch/login/restart cycles retry with exponential backoff using configured base\ndelay, doubling to a maximum one-hour interval. Do not impose a finite three-client-\nrestart terminal budget; retries continue until verified recovery or explicit STOP/\nconfiguration/client replacement. Every replacement again uses the 10-second settle and\nshared three-hotkey verifier.\n\n'''
text = text[:start] + policy + text[end:]
save(pth,text,crlf)

# Release notes are the public contract for this stabilization release.
Path('RELEASE-NOTES.md').write_text('''# 4RTools Vanilla 0.6.43\n\n## Restart-only Autobattle/slave hotkeys\n\nAutomatic resume hotkeys are no longer a steady-state wakeup mechanism. Restoring,\nmaximizing, focusing or merely observing an already-running client does not send the\nconfigured hotkey. Automatic hotkey input is authorized only after 4RTools itself\nfreshly launches/restarts/relogs that character.\n\nAfter verified username/character/X/Y/map/living-HP readiness, 4RTools waits a full\n10 seconds and then invokes the same shared ResumeHotkey verifier used by\nTESTS -> Resume hotkey. That verifier allows three total sends, each followed by its\nown 10-second fresh X/Y movement window, and stops immediately when either axis moves.\n\n## Five/ten-minute steady-state movement recovery\n\nNormal supervision now watches verified X/Y only and sends no wakeup hotkey. At five\nminutes without verified movement, a freshly confirmed exact `Now Logging Out.` or\n`Disconnected from Server.` popup can trigger an early restart. If neither popup is\npresent, 4RTools keeps waiting. At ten minutes without verified X/Y movement, the\naffected client is restarted regardless of visual classification. Unknown, stale,\nunreadable and unverified coordinates remain invalid rather than becoming `(0,0)`.\n\nRecovery stays per-client and globally serialized. A healthy sibling is not disturbed.\nFailed restart/login cycles use the existing exponential retry delay, doubling from the\nconfigured base interval and capping at one hour between attempts. There is no longer a\nthree-client-restart permanent-stop budget; retries continue until recovery succeeds or\nthe user presses STOP/changes ownership or configuration.\n\n## Existing 0.6.42 safeguards retained\n\nCursor-aware minimization remains: automatic minimize requires at least 60 seconds with\nthe client non-minimized and 60 seconds without machine cursor movement. Launcher GAME\nSTART remains single-action and deliberately paced with stable semantic/visual evidence.\nCharacter selection remains keyboard/state based rather than screen-coordinate based.\n\n## Validation limits\n\nRelease validation covers Debug/Release regression suites, the shared three-attempt\nresume verifier, restart-only ownership gating, five/ten-minute watchdog boundaries,\nterminal-popup confirmation, exponential backoff to one hour, dual-client serialization,\nnative test-owned process recovery, portable package/launch checks and mock-data UI\nchecks. Public release assets, source identity and updater discovery are verified after\npublication. No independent live Vanilla/Gepard/RDP session is available to the build\nrunner; the user-provided screenshots/logs are the live evidence for the corrected bug.\n''', encoding='utf-8')

# README/package wording: no 30-second hotkey wakeups and 10-second settle.
for doc in ['README.md','packaging/README.txt']:
    pth, text, crlf = load(doc)
    text = text.replace('7-second', '10-second').replace('7 seconds', '10 seconds').replace('7s', '10s')
    text = text.replace('30 seconds without verified X/Y movement', '10 minutes without verified X/Y movement')
    save(pth,text,crlf)

# Sanity gates: removed finite restart state must not survive in production/tests.
for path in ['Model/Vanilla/VanillaReconnect.cs','Model/Vanilla/VanillaAutobattleResume.cs','Model/Vanilla/VanillaStartupOrchestrator.cs','Model/Vanilla/VanillaTerminalRecovery.cs']:
    text = Path(path).read_text(encoding='utf-8')
    for token in ['AutobattleRestartAttempts','AutobattleRestartInProgress','AutobattleRecoveryExhausted','MaximumClientRestarts']:
        assert token not in text, (path, token)

print('Restart-only hotkey and five/ten-minute recovery transformation applied.')
